import json, re

with open('/workspace/data/public/labels.jsonl') as f:
    labels = {l['set_id']: l for l in [json.loads(line) for line in f]}

with open('/workspace/data/public/questions.jsonl') as f:
    questions = [json.loads(line) for line in f]

for q in questions:
    print(f"QID: {q['qid']} | Drug: {q['drug_name']} | Question: {q['question']}")
    set_id = q['set_id']
    label = labels[set_id]

    keywords = []
    q_lower = q['question'].lower()
    if 'interaction' in q_lower:
        keywords = ['interaction', 'contraindication']
    elif 'avoid' in q_lower:
        keywords = ['avoid', 'contraindication', 'interaction']
    elif 'administer' in q_lower:
        keywords = ['administration', 'dosage', 'how to']
    elif 'dosage' in q_lower or 'dose' in q_lower:
        keywords = ['dosage', 'administration', 'regimen']
    elif 'safety' in q_lower or 'risk' in q_lower:
        keywords = ['warning', 'precaution', 'adverse', 'risk', 'safety']
    elif 'warning' in q_lower or 'precaution' in q_lower:
        keywords = ['warning', 'precaution']

    print("Matches:")
    for i, chunk in enumerate(label['chunks']):
        for kw in keywords:
            if re.search(r'\b' + kw + r'\b', chunk, re.IGNORECASE):
                first_line = chunk.strip().split('\n')[0]
                if len(first_line) < 100:
                    print(f"  PASSAGE_{i:04d}: {first_line}")
                break
    print()
